var leastOpsExpressTarget = function(x, target) {
    const memo = new Map();

    function dp(t) {
        if (t < x) return Math.min(2 * t - 1, 2 * (x - t));
        if (memo.has(t)) return memo.get(t);

        let k = 0;
        let p = 1;
        while (p * x <= t) {
            p *= x;
            k++;
        }
        if (t === p) {
            memo.set(t, k - 1);
            return k - 1;
        }

        let ans = dp(t - p) + k;
        if (p * x - t < t) {
            ans = Math.min(ans, dp(p * x - t) + k + 1);
        }
        memo.set(t, ans);
        return ans;
    }

    return dp(target);
};
